const cards = (items, cls = '') => `<div class="info-grid ${cls}">${items.map(i => `<article class="info-card"><span class="info-card-mark" aria-hidden="true">${i.mark || '•'}</span><h3>${i.title}</h3><p>${i.copy}</p>${i.link ? `<a class="text-link" href="${i.link.href}">${i.link.label} <span aria-hidden="true">→</span></a>` : ''}</article>`).join('')}</div>`;
const brandCards = (items, cls = '') => `<div class="brand-grid ${cls}">${items.map(i => `<article class="brand-card"><div class="brand-logo-frame"><img src="${i.logo}" alt="${i.alt}" width="${i.width}" height="${i.height}" loading="lazy" decoding="async"></div><h3>${i.title}</h3><p>${i.copy}</p>${i.note ? `<p class="brand-card-note">${i.note}</p>` : ''}</article>`).join('')}</div>`;
const list = items => `<ul class="check-list">${items.map(item => `<li>${item}</li>`).join('')}</ul>`;
const faq = items => `<div class="faq-list">${items.map((i, index) => `<details class="faq-item" ${index === 0 ? 'open' : ''}><summary>${i.q}</summary><div>${i.html || `<p>${i.a}</p>`}</div></details>`).join('')}</div>`;
const priceTable = (caption, rows, note = '') => `<div class="price-table-wrap"><table class="price-table"><caption>${caption}</caption><thead><tr><th scope="col">Option</th><th scope="col">Price</th></tr></thead><tbody>${rows.map(r => `<tr><th scope="row">${r[0]}</th><td>${r[1]}</td></tr>`).join('')}</tbody></table>${note ? `<p class="table-note">${note}</p>` : ''}</div>`;
const cta = (title, copy, actions) => `<section class="section cta-band"><div class="container cta-band-inner"><div><p class="section-kicker section-kicker-light">Next step</p><h2>${title}</h2><p>${copy}</p></div><div class="button-row">${actions.join('')}</div></div></section>`;
const hero = ({ kicker, title, copy, image, alt, actions = [], position = '', actionsClass = '' }) => `<section class="interior-hero"><div class="container interior-hero-grid"><div class="interior-hero-copy"><p class="eyebrow">${kicker}</p><h1>${title}</h1><p>${copy}</p>${actions.length ? `<div class="button-row${actionsClass ? ` ${actionsClass}` : ''}">${actions.join('')}</div>` : ''}</div>${image ? `<div class="interior-hero-media"><img src="${image}" alt="${alt}" width="1200" height="900" fetchpriority="high" decoding="async" ${position ? `style="object-position:${position}"` : ''}></div>` : `<div class="interior-hero-shape" aria-hidden="true"><span>Jollytails<br>Resort</span></div>`}</div></section>`;
const split = ({ image, alt, kicker, title, body, reverse = false, position = '', imageClass = '' }) => `<div class="split-section ${reverse ? 'split-section-reverse' : ''}"><div class="split-photo"><img${imageClass ? ` class="${imageClass}"` : ''} src="${image}" alt="${alt}" width="1200" height="900" loading="lazy" decoding="async" ${position ? `style="object-position:${position}"` : ''}></div><div class="split-copy"><p class="section-kicker">${kicker}</p><h2>${title}</h2>${body}</div></div>`;

function page({ path, title, description, body, schema = '' }) {
  const canonical = `https://jollytailsresort.ca${path === '/' ? '/' : path}`;
  const html = `<!doctype html>
<html lang="en-CA"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>${title} | Jollytails Resort</title><meta name="description" content="${description}"><meta name="robots" content="noindex, nofollow, noarchive"><link rel="canonical" href="${canonical}">
<meta property="og:locale" content="en_CA"><meta property="og:type" content="website"><meta property="og:site_name" content="Jollytails Resort"><meta property="og:title" content="${title} | Jollytails Resort"><meta property="og:description" content="${description}"><meta property="og:url" content="${canonical}"><meta property="og:image" content="https://jollytailsresort.ca/assets/daycare-dog.webp"><meta property="og:image:alt" content="Dogs playing together at Jollytails Resort"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="${title} | Jollytails Resort"><meta name="twitter:description" content="${description}"><meta name="twitter:image" content="https://jollytailsresort.ca/assets/daycare-dog.webp"><meta name="theme-color" content="#244f86"><link rel="icon" href="/assets/favicon-32.png" type="image/png" sizes="32x32"><link rel="icon" href="/assets/favicon.png" type="image/png" sizes="512x512"><link rel="apple-touch-icon" href="/assets/apple-touch-icon.png" sizes="180x180"><link rel="stylesheet" href="/styles.css"><script src="/site.js" defer></script>${schema}
</head><body id="top"><a class="skip-link" href="#main-content">Skip to main content</a>${nav}<main id="main-content">${body}</main>${footer}</body></html>\n`;
  return html;
}

