add('gallery.html', {
  path:'/gallery', title:'Jollytails Resort Photo Gallery', description:'See a curated gallery of daycare play, grooming, retail, and everyday life at Jollytails Resort.',
  body: hero({kicker:'Photo Gallery',title:'Real dogs. Real Resort days.',copy:'A look at playtime, quiet moments, fresh grooms, and the familiar spaces our guests enjoy at Jollytails Resort.',image:img.galleryHero,alt:'A brindle and white dog looking closely into the camera in the Resort play yard',position:'50% 47%'}) +
  `<section class="section"><div class="container"><div class="gallery-grid">${galleryImages.map((g,index)=>`<a class="gallery-item" href="${g[0]}" data-gallery-item data-gallery-index="${index}" aria-label="View full-size photo: ${g[1]}"><img src="${g[0]}" alt="${g[1]}" loading="lazy" decoding="async" style="object-position:${g[2]}"></a>`).join('')}</div></div></section>` + cta('Picture your dog here?','Start with the service that fits your dog and follow the new-client or returning-client path.',[button('/reservations','Reservation Options','button-light')])
});

add('careers.html', {
  path:'/careers', title:'Careers At Jollytails Resort', description:'Explore current daycare, boarding, grooming, retail, and overnight career opportunities at Jollytails Resort.',
  body: hero({kicker:'Careers',title:'Bring your energy. Build a career around dogs.',copy:'Join a busy, friendly local team working across pet retail, supervised daycare and boarding, grooming, and overnight care.',image:img.beds,alt:'A group of dogs gathered together inside Jollytails Resort',actions:[button('mailto:info@jollytailsresort.ca?subject=Jollytails%20Resort%20Career%20Application','Email Your Application'),button('https://jollytails.ca/hiring-portal','Apply Online','button-outline','target="_blank" rel="noopener"')]}) +
  `<section class="section"><div class="container">${sectionHead('Why Work Here','A practical place to grow your pet-care experience.')} ${cards([
    {mark:'Care',title:'Health Benefits',copy:'Eligible employees can access cost-shared health, medical, dental, and paramedical coverage.'},
    {mark:'Pets',title:'Employee Pet Perks',copy:'Discounts on pet products and complimentary feeding programs are available.'},
    {mark:'Grow',title:'Flexible Paths',copy:'Flexible schedules and opportunities for advancement across Resort operations.'}
  ])}</div></section>` +
  `<section class="section section-sky"><div class="container">${sectionHead('Current Opportunities','Roles presently listed by the Resort.','Applicants need reliable transportation for shifts within operating hours of 6:30am–7:30pm.')}<div class="job-grid">${[
    ['Full-Time Doggy Daycare And Boarding Attendant','Supervise safe group play, support cleaning and routines, and help dogs move comfortably through their day.'],['Overnight Boarding Attendant','Support overnight guests and facility routines while dogs are staying at the Resort.'],['Pet Products Expert / Front Desk','Welcome clients, support retail purchases, and help keep Resort communication organized.'],['Experienced Groomer · Full-Time','Provide comfort-focused grooming and communicate clearly with clients about each appointment.']
  ].map(j=>`<article class="job-card"><p class="card-tag">Current listing</p><h3>${j[0]}</h3><p>${j[1]}</p><a class="text-link" href="mailto:info@jollytailsresort.ca?subject=${encodeURIComponent(j[0])}">Apply By Email →</a></article>`).join('')}</div></div></section>` +
  `<section class="section"><div class="container content-two-col"><div>${sectionHead('How To Apply','Tell us what you would bring to the team.')}<p>Send a resume and short introduction to <a href="mailto:info@jollytailsresort.ca">info@jollytailsresort.ca</a>, or use the existing Jollytails hiring portal.</p><div class="button-row">${button('mailto:info@jollytailsresort.ca?subject=Jollytails%20Resort%20Career%20Application','Email The Resort')}${button('https://jollytails.ca/hiring-portal','Open Hiring Portal','button-outline','target="_blank" rel="noopener"')}</div></div><aside class="callout-card"><p class="card-tag">Before You Apply</p><h2>Working with dogs is active work.</h2><p>Roles can include cleaning, standing, lifting, outdoor work, early or late shifts, and supporting dogs with different needs and play styles.</p></aside></div></section>`
});

